{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Lycopene, a highly lipophilic polyisoprenoid with no ionizable groups, had only 0.17% of an oral dose reach the circulation, indicating very low systemic availability for a structurally related long-chain isoprenoid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, despite extremely low aqueous solubility, achieved approximately 40% oral bioavailability in humans, showing that high lipophilicity alone does not always preclude F≥20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Finerenone showed 43.5% absolute bioavailability in humans, a high-transfer result, but the molecule is a small heterocycle with hydrogen-bonding groups, unlike the query's large polyprenyl quinone.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an extremely lipophilic, high-molecular-weight polyprenyl quinone with no ionizable groups. The most chemically analogous evidence, lycopene, shows very low oral systemic availability (0.17–2.6%), supporting F<20%. High-transfer small-molecule drugs with F>20% are not chemically transferable because they are much smaller, less lipophilic, and often ionizable. Etretinate, a lipophilic retinoid, shows ~40% F, but its much lower molecular weight and logP limit its applicability. The physicochemical prior (low) and the lycopene analogy outweigh the non-analogous high-F data.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for the query molecule (CoQ9/10) in humans.",
    "The effect of the polar quinone head on absorption relative to pure hydrocarbons like lycopene is unquantified.",
    "Formulation and food effects, which can markedly alter absorption of lipophilic compounds, are not represented in the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

